resource_api_reproduction.test_source:
// External acceptance of existing CLI resource inputs through the public API.
// Only the error class and a usable source position are required.

///|
fn external_limit_location(d : @moonjsonnet.Diagnostic) -> Unit raise {
  assert_eq(d.kind, @moonjsonnet.Limit)
  assert_true(!d.location.file.is_empty())
  assert_true(d.location.line > 0)
  assert_true(d.location.column > 0)
}

///|
test "independent public API resource errors retain kind and source position" {
  let defaults = @moonjsonnet.Limits::default()
  for
    (source, limits) in [
      ("std.range(0,100)", { ..defaults, steps: 10, }),
      ("local f(x)=f(x+1); f(0)", { ..defaults, depth: 20, }),
      ("'😀😀'", { ..defaults, output_bytes: 8, }),
    ] {
    let program = @moonjsonnet.Program::parse(source, filename="main.jsonnet")
    try program.evaluate_text(limits~) catch {
      @moonjsonnet.Error(d) => external_limit_location(d)
    } noraise {
      _ => fail("public API accepted a resource-limited configuration")
    }
  }
  try @fs.evaluate_file(
    "direct-resource/main.jsonnet",
    limits={ ..defaults, import_bytes: 2, },
  ) catch {
    @moonjsonnet.Error(d) => external_limit_location(d)
  } noraise {
    _ => fail("public API accepted an import exceeding its byte limit")
  }
  // Keep the prior four-case controller's exact-output positive boundary.
  let exact = @moonjsonnet.Program::parse("'😀'", filename="main.jsonnet")
  assert_eq(
    @json.parse(exact.evaluate_text(limits={ ..defaults, output_bytes: 6, })),
    Json::string("😀"),
  )
}
